//! `run_search` — rebuild the project's `SearchResult` set for the current query.
//!
//! ## Matching
//!
//! Matching goes through **`text_document::matching`** — the *same* matcher the editor's
//! own find and find-and-replace use. It is not this crate's own: two matchers drift, and
//! a writer meets that drift as "the editor found it but the search panel didn't". So
//! case folding (offset-correct, even where folding changes a string's length) and the
//! prose-correct word boundary (whole-word `Elena` finds `Elena's`) are already right
//! here, because they are right *there*.
//!
//! Still to land, per the plan:
//!
//!   * per-scene language resolution + diacritic folding (`Aurelien` finds `Aurélien`) —
//!     until then `diacritic_sensitive` is a **dead** flag: the DTO takes it, the `Search`
//!     entity stores it, and nothing reads it.
//!   * **plain-text extraction from Djot.** This still scans the raw `Content.data`, which
//!     is *markup*: a search for `http` hits link URLs, and an occurrence count taken from
//!     the source will not agree with what a parsed replace re-derives — which would make
//!     `replace_in_project`'s "the text moved under us" guard fire on perfectly good rows.
//!   * a versioned corpus cache (re-parsing 4000 rows per keystroke is not viable).
//!
//! What *is* already real and must not regress:
//!
//!   * **Bulk writes.** The old rows go in one `remove_search_result_multi` and the
//!     new ones in one `create_search_result_multi` — never a per-row loop. This is
//!     what keeps the event count independent of the result count.
//!   * **One row per matching FIELD**, carrying `occurrence_count` — not one row per
//!     occurrence. Per-occurrence review happens in the preview, recomputed live.
//!   * **No stored offsets.** A snippet is a display hint; positions are re-derived
//!     against the live document at activation time. See the manifest for why.
//!   * **`RESULT_CAP`.** A common word in a novel matches thousands of times; the row
//!     set is bounded and `truncated` is reported so the UI can disable Replace All
//!     (a truncated scan cannot honestly claim completeness).

use crate::RunSearchDto;
use crate::RunSearchResultDto;
use anyhow::{Result, anyhow};
use common::database::CommandUnitOfWork;
use common::direct_access::binder::BinderRelationshipField;
use common::direct_access::binder_item::BinderItemRelationshipField;
use common::direct_access::search::SearchRelationshipField;
use common::direct_access::work::WorkRelationshipField;
use common::entities::{
    Binder, BinderItem, Content, ContentRole, MatchField, Search, SearchResult, Work, WorkInfo,
};
use common::types::EntityId;
use text_document::matching::MatchOptions;

/// Most rows we will keep for one search. A common word ("said", "elle") matches
/// thousands of times in a novel; past this we stop scanning and set `truncated`.
const RESULT_CAP: usize = 300;

/// How much context a result row carries either side of the match.
const SNIPPET_CONTEXT: usize = 60;

pub trait RunSearchUnitOfWorkFactoryTrait: Send + Sync {
    fn create(&self) -> Box<dyn RunSearchUnitOfWorkTrait>;
}

// Exactly the same macros must be set in ../units_of_work/run_search_uow.rs
//
// Read-write UoW: it reads the binder tree and writes the result set, so every
// action is the write-capable variant (no `…RO`) — read-only and write actions must
// not be mixed in one unit of work.
#[macros::uow_action(entity = "WorkInfo", action = "Get")]
#[macros::uow_action(entity = "WorkInfo", action = "GetAll")]
#[macros::uow_action(entity = "Search", action = "Get")]
#[macros::uow_action(entity = "Search", action = "Update")]
#[macros::uow_action(entity = "Search", action = "GetRelationship")]
#[macros::uow_action(entity = "SearchResult", action = "CreateMulti")]
#[macros::uow_action(entity = "SearchResult", action = "RemoveMulti")]
